mapper.select:
SELECT c.id, c.doc_revision_id, c.embedding
FROM cw_knowledge_chunk c
JOIN cw_knowledge_version v ON v.kb_version_id = c.kb_version_id AND v.tenant_id = c.tenant_id
WHERE c.tenant_id = #{tenantId} AND c.kb_version_id = #{kbVersionId}
  AND v.access_status = 'READY' AND c.acl_mode = 'PUBLIC'
  AND c.id > #{afterId}

      AND c.doc_revision_id IN
      #{p}

ORDER BY c.id
LIMIT #{limit}

mapper.delete:
DELETE FROM cw_knowledge_chunk WHERE kb_version_id = #{versionId}

    AND id NOT IN
    #{id}
